def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]

    # Immediate read of the last move
    last_op = op[-1]
    last_me = me[-1]

    # Always defect against pure defector
    if 'C' not in op:
        return 'D'
    # Always exploit pure cooperator, but keep some early cooperation for safety
    if 'D' not in op:
        if n < 8:
            return 'C'
        return 'D'

    # Count defections
    op_d = n - op.count('C')
    # If opponent is mostly defecting, defect
    if op_d * 2 >= n:
        # Break out occasionally to try to restore cooperation if there's
        # a sign of forgiveness
        if last_op == 'C' and op_d * 3 > n * 2:
            return 'C'
        return 'D'

    # Long-run cooperation detection
    op_c = n - op_d

    # Detect cooperation streaks
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    # Endgame: exploit established cooperation if opponent is very cooperative
    if n >= 96:
        if op_c * 10 >= n * 8:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # If we're in a mutual defection streak, attempt to repair with C sometimes
    if last_op == 'D' and last_me == 'D':
        if streak_d >= 2:
            # Forgiveness attempt: if opponent has been cooperative often,
            # give a cooperating signal to see if they reciprocate
            if op_c * 2 > n and rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just defected once after cooperation
    if last_op == 'D' and last_me == 'C':
        # Retaliate, but not too long
        if streak_d == 1:
            # Quick punishment, then forgive
            if op_c * 2 > n:
                # forgive soon if they've been nice overall
                return 'D'
            return 'D'
        # Multiple defections in a row: punish harder
        if streak_d >= 3:
            return 'D'
        return 'D'

    # Opponent cooperated; respond kindly
    if last_op == 'C':
        # Occasional probe only when we're clearly ahead and opponent very cooperative
        if n > 20 and op_c * 10 >= n * 9:
            # Probe rarely to test exploitation, then retreat if punished
            if last_me == 'D' and streak_d >= 1:
                return 'C'
            if n % 11 == 0 and rng.random() < 0.15:
                return 'D'
            return 'C'
        if last_me == 'D':
            # Signal return to cooperation
            return 'C'
        return 'C'

    return 'C'
